1	import { supabase } from '../lib/supabase';
2	import { invokeFunction } from './api';
3	import { logError } from '../lib/logger';
4	
5	export interface Wallet {
6	    id: string;
7	    user_id: string;
8	    balance: number;
9	    user_type: 'company' | 'worker';
10	    asaas_customer_id?: string;
11	    created_at: string;
12	    updated_at: string;
13	}
14	
15	export interface WalletTransaction {
16	    id: string;
17	    wallet_id: string;
18	    amount: number;
19	    type: 'credit' | 'debit' | 'escrow_reserve' | 'escrow_release' | 'initial_balance' | 'platform_fee';
20	    description: string | null;
21	    reference_id: string | null;
22	    created_at: string;
23	}
24	
25	export interface EscrowTransaction {
26	    id: string;
27	    job_id: string;
28	    application_id: string | null;
29	    amount: number;
30	    company_wallet_id: string;
31	    worker_wallet_id: string | null;
32	    status: 'reserved' | 'released' | 'refunded';
33	    created_at: string;
34	    released_at: string | null;
35	    job?: { title: string };
36	}
37	
38	export const WalletService = {
39	    async getOrCreateWallet(userId: string, userType: 'company' | 'worker'): Promise<Wallet | null> {
40	        const { data: existing } = await supabase
41	            .from('wallets')
42	            .select('*')
43	            .eq('user_id', userId)
44	            .single();
45	
46	        if (existing) return existing as Wallet;
47	
48	        const { data: newWallet, error } = await supabase
49	            .from('wallets')
50	            .insert({ user_id: userId, balance: 0.00, user_type: userType })
51	            .select()
52	            .single();
53	
54	        if (error) {
55	            logError('Error creating wallet', error);
56	            return null;
57	        }
58	
59	        return newWallet as Wallet;
60	    },
61	
62	    async withdrawFunds(amount: number, pixKey: string, pixKeyType: string = 'CPF'): Promise<{ success: boolean; error?: string }> {
63	        try {
64	            await invokeFunction('asaas-withdraw', { amount, pixKey, pixKeyType });
65	            return { success: true };
66	        } catch (error: unknown) {
67	            logError('Error withdrawing funds', error);
68	            return { success: false, error: error instanceof Error ? error.message : 'Erro ao realizar saque' };
69	        }
70	    },
71	
72	    async getBalance(userId: string): Promise<number> {
73	        const { data } = await supabase
74	            .from('wallets')
75	            .select('balance')
76	            .eq('user_id', userId)
77	            .single();
78	
79	        return data?.balance || 0;
80	    },
81	
82	    async getTransactions(userId: string): Promise<WalletTransaction[]> {
83	        const { data: wallet } = await supabase
84	            .from('wallets')
85	            .select('id')
86	            .eq('user_id', userId)
87	            .single();
88	
89	        if (!wallet) return [];
90	
91	        const { data } = await supabase
92	            .from('wallet_transactions')
93	            .select('*')
94	            .eq('wallet_id', wallet.id)
95	            .order('created_at', { ascending: false });
96	
97	        return (data || []) as WalletTransaction[];
98	    },
99	
100	    async reserveEscrow(jobId: string, amount: number, companyUserId: string): Promise<{ success: boolean; error?: string }> {
101	        try {
102	            const { error: rpcError } = await supabase.rpc('reserve_escrow', {
103	                p_job_id: jobId,
104	                p_amount: amount,
105	                p_company_user_id: companyUserId
106	            });
107	
108	            if (rpcError) {
109	                if (rpcError.message?.includes('Saldo insuficiente')) {
110	                    return { success: false, error: rpcError.message };
111	                }
112	                if (rpcError.message?.includes('Carteira nao encontrada')) {
113	                    return { success: false, error: 'Carteira nao encontrada' };
114	                }
115	                if (rpcError.code === '23505') {
116	                    return { success: false, error: 'Escrow ja existe para esta vaga' };
117	                }
118	                throw rpcError;
119	            }
120	
121	            return { success: true };
122	        } catch (error) {
123	            logError('Error reserving escrow', error);
124	            return { success: false, error: 'Erro ao reservar pagamento' };
125	        }
126	    },
127	
128	    async createDeposit(payload: { amount: number, name?: string, cpfCnpj?: string, billingType?: string }): Promise<{ paymentId?: string; invoiceUrl?: string; pixQrCodeUrl?: string; error?: string }> {
129	        try {
130	            return await invokeFunction('asaas-deposit', payload);
131	        } catch (error: unknown) {
132	            logError('Error creating deposit', error);
133	            return { error: error instanceof Error ? error.message : 'Erro ao criar deposito via Asaas' };
134	        }
135	    },
136	
137	    async syncBalance(): Promise<{ success: boolean; hasUpdates?: boolean; totalSynced?: number; message?: string; error?: string }> {
138	        try {
139	            return await invokeFunction('asaas-sync', {});
140	        } catch (error: unknown) {
141	            logError('Error syncing balance', error);
142	            return { success: false, error: error instanceof Error ? error.message : 'Erro ao sincronizar saldo' };
143	        }
144	    },
145	
146	    async releaseEscrow(jobId: string, applicationId: string, workerUserId: string): Promise<{ success: boolean; error?: string }> {
147	        try {
148	            await invokeFunction('asaas-checkout', { jobId, applicationId, workerId: workerUserId });
149	            return { success: true };
150	        } catch (error: unknown) {
151	            logError('Error releasing escrow', error);
152	            return { success: false, error: error instanceof Error ? error.message : 'Erro ao liberar pagamento' };
153	        }
154	    },
155	
156	    async refundEscrow(jobId: string, reason?: string): Promise<{ success: boolean; error?: string }> {
157	        try {
158	            const { error: rpcError } = await supabase.rpc('refund_escrow', {
159	                p_job_id: jobId,
160	                p_reason: reason || 'Reembolso de vaga cancelada'
161	            });
162	
163	            if (rpcError) {
164	                if (rpcError.message?.includes('No reserved escrow')) {
165	                    return { success: true };
166	                }
167	                throw rpcError;
168	            }
169	
170	            return { success: true };
171	        } catch (error) {
172	            logError('Error refunding escrow', error);
173	            return { success: false, error: 'Erro ao reembolsar' };
174	        }
175	    },
176	
177	    async getJobEscrow(jobId: string): Promise<EscrowTransaction | null> {
178	        const { data } = await supabase
179	            .from('escrow_transactions')
180	            .select('*')
181	            .eq('job_id', jobId)
182	            .single();
183	
184	        return data as EscrowTransaction | null;
185	    },
186	
187	    async getCompanyEscrows(companyUserId: string): Promise<EscrowTransaction[]> {
188	        const { data: wallet } = await supabase
189	            .from('wallets')
190	            .select('id')
191	            .eq('user_id', companyUserId)
192	            .single();
193	
194	        if (!wallet) return [];
195	
196	        const { data } = await supabase
197	            .from('escrow_transactions')
198	            .select('*, job:jobs(title)')
199	            .eq('company_wallet_id', wallet.id)
200	            .order('created_at', { ascending: false });
201	
202	        return (data || []) as EscrowTransaction[];
203	    }
204	};
