6	function validateCPF(cpf: string): boolean {
7	    if (cpf.length !== 11) return false;
8	    if (/^(\d)\1{10}$/.test(cpf)) return false;
9	
10	    const digits = cpf.split('').map(Number);
11	    // First check digit
12	    let sum = 0;
13	    for (let i = 0; i < 9; i++) sum += digits[i] * (10 - i);
14	    let remainder = (sum * 10) % 11;
15	    if (remainder === 10) remainder = 0;
16	    if (remainder !== digits[9]) return false;
17	
18	    // Second check digit
19	    sum = 0;
20	    for (let i = 0; i < 10; i++) sum += digits[i] * (11 - i);
21	    remainder = (sum * 10) % 11;
22	    if (remainder === 10) remainder = 0;
23	    if (remainder !== digits[10]) return false;
24	
25	    return true;
26	}
27	
28	function validateCNPJ(cnpj: string): boolean {
29	    if (cnpj.length !== 14) return false;
30	    if (/^(\d)\1{13}$/.test(cnpj)) return false;
31	
32	    const digits = cnpj.split('').map(Number);
33	    const weights1 = [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
34	    const weights2 = [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2];
35	
36	    // First check digit
37	    let sum = 0;
38	    for (let i = 0; i < 12; i++) sum += digits[i] * weights1[i];
39	    let remainder = sum % 11;
40	    const check1 = remainder < 2 ? 0 : 11 - remainder;
41	    if (check1 !== digits[12]) return false;
42	
43	    // Second check digit
44	    sum = 0;
45	    for (let i = 0; i < 13; i++) sum += digits[i] * weights2[i];
46	    remainder = sum % 11;
47	    const check2 = remainder < 2 ? 0 : 11 - remainder;
48	    if (check2 !== digits[13]) return false;
49	
50	    return true;
51	}
