53	serve(async (req) => {
54	    const corsHeaders = getCorsHeaders(req);
55	    if (req.method === 'OPTIONS') {
56	        return new Response('ok', { headers: corsHeaders });
57	    }
58	
59	    try {
60	        const supabaseAdmin = createClient(
61	            Deno.env.get('SUPABASE_URL') ?? '',
62	            Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
63	        );
64	
65	        const authHeader = req.headers.get('Authorization');
66	        if (!authHeader) throw new Error('Missing Authorization header');
67	        const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : authHeader;
68	        const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);
69	        if (userError || !user) throw new Error('Invalid Token');
70	
71	        if (isRateLimited(user.id, 'deposit', 5, 60_000)) {
72	            return new Response(JSON.stringify({ error: 'Muitas tentativas. Aguarde 1 minuto.' }), {
73	                headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429
74	            });
75	        }
76	
77	        const { amount, name, cpfCnpj, billingType } = await req.json();
78	
79	        if (!amount || typeof amount !== 'number' || amount < 50) {
80	            throw new Error('Valor mínimo para depósito é R$ 50,00');
81	        }
82	        if (amount > 50000) {
83	            throw new Error('Maximum deposit amount is R$ 50,000.00');
84	        }
85	        // Ensure 2 decimal places precision
86	        const sanitizedAmount = Math.round(amount * 100) / 100;
87	
88	        // Ensure wallet exists
89	        const { data: wallet } = await supabaseAdmin
90	            .from('wallets')
91	            .select('id, asaas_customer_id')
92	            .eq('user_id', user.id)
93	            .single();
94	
95	        if (!wallet) {
96	            throw new Error('Wallet not found. Please complete onboarding first.');
97	        }
98	
99	        let customerId = wallet.asaas_customer_id;
100	
101	        // Create a customer on the master account if not exists
102	        if (!customerId) {
103	            const cleanDoc = cpfCnpj ? cpfCnpj.replace(/\D/g, '') : '';
104	            if (cleanDoc.length === 11) {
105	                if (!validateCPF(cleanDoc)) {
106	                    throw new Error('CPF inválido. Verifique os dígitos e tente novamente.');
107	                }
108	            } else if (cleanDoc.length === 14) {
109	                if (!validateCNPJ(cleanDoc)) {
110	                    throw new Error('CNPJ inválido. Verifique os dígitos e tente novamente.');
111	                }
112	            } else {
113	                throw new Error('CPF (11 dígitos) ou CNPJ (14 dígitos) é obrigatório para criar conta de pagamento.');
114	            }
115	            const finalDoc = cleanDoc;
116	
117	            const customerPayload = {
118	                name: name || 'Worki User',
119	                cpfCnpj: finalDoc
120	            };
121	
122	            const customerRes = await fetch(`${ASAAS_API_URL}/customers`, {
123	                method: 'POST',
124	                headers: getAsaasHeaders(),
125	                body: JSON.stringify(customerPayload)
126	            });
127	            const customerData = await customerRes.json();
128	
129	            if (!customerRes.ok) {
130	                console.error('Customer Details:', customerData);
131	                throw new Error(customerData.errors?.[0]?.description || 'Error creating Asaas customer');
132	            }
133	
134	            customerId = customerData.id;
135	
136	            await supabaseAdmin.from('wallets').update({ asaas_customer_id: customerId }).eq('user_id', user.id).throwOnError();
137	        }
138	
139	        // Create charge on master account — accepts PIX, Boleto, or Credit Card
140	        const dueDate = new Date();
141	        dueDate.setDate(dueDate.getDate() + 3); // 3 days for boleto
142	
143	        const allowedTypes = ['PIX', 'BOLETO', 'CREDIT_CARD', 'UNDEFINED'];
144	        const selectedType = allowedTypes.includes(billingType) ? billingType : 'UNDEFINED';
145	
146	        const paymentPayload: Record<string, unknown> = {
147	            customer: customerId,
148	            billingType: selectedType,
149	            value: sanitizedAmount,
150	            dueDate: dueDate.toISOString().split('T')[0],
151	            description: `Deposito de Creditos - Worki`,
152	            externalReference: user.id,
153	        };
154	
155	        // Credit card installments (if applicable)
156	        if (selectedType === 'CREDIT_CARD' && sanitizedAmount >= 100) {
157	            paymentPayload.maxInstallmentCount = Math.min(Math.floor(sanitizedAmount / 50), 6);
158	        }
159	
160	        const paymentRes = await fetch(`${ASAAS_API_URL}/payments`, {
161	            method: 'POST',
162	            headers: getAsaasHeaders(),
163	            body: JSON.stringify(paymentPayload)
164	        });
165	
166	        const paymentData = await paymentRes.json();
167	        if (!paymentRes.ok) throw new Error(paymentData.errors?.[0]?.description || 'Erro ao gerar cobranca');
168	
169	        return new Response(JSON.stringify({
170	            success: true,
171	            paymentId: paymentData.id,
172	            invoiceUrl: paymentData.invoiceUrl,
173	            billingType: selectedType,
174	            pixQrCodeUrl: paymentData.invoiceUrl
175	        }), {
176	            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
177	            status: 200
178	        });
179	
180	    } catch (error: any) {
181	        console.error('Deposit Error:', error);
182	        return new Response(JSON.stringify({ error: error.message }), {
183	            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
184	            status: 400,
185	        });
186	    }
187	});
