26	                headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 429
27	            });
28	        }
29	
30	        const { amount, pixKey, pixKeyType } = await req.json();
31	
32	        if (!amount || typeof amount !== 'number' || amount < 5) throw new Error('Minimum withdrawal amount is R$ 5.00');
33	        if (amount > 50000) throw new Error('Maximum withdrawal amount is R$ 50,000.00');
34	        if (!pixKey) throw new Error('Pix Key is required');
35	
36	        // 1. Get user wallet (virtual balance)
37	        const { data: userWallet } = await supabaseAdmin
38	            .from('wallets')
39	            .select('id, balance')
40	            .eq('user_id', user.id)
41	            .single();
42	
43	        if (!userWallet) throw new Error('Wallet not found');
44	        if (userWallet.balance < amount) throw new Error('Insufficient balance');
45	
46	        // Calculate Platform Fee (R$3 fixed + 5% service fee)
47	        const WITHDRAW_FEE_FIXED = 3.00;
48	        const WITHDRAW_FEE_PERCENTAGE = 5;
49	        const percentageFee = parseFloat(((amount * WITHDRAW_FEE_PERCENTAGE) / 100).toFixed(2));
50	        const feeAmount = parseFloat((WITHDRAW_FEE_FIXED + percentageFee).toFixed(2));
51	        const netAmount = parseFloat((amount - feeAmount).toFixed(2));
52	
53	        // 2. Atomically deduct balance FIRST (will fail if insufficient due to CHECK constraint)
54	        const { error: balanceError } = await supabaseAdmin.rpc('update_wallet_balance', {
55	            p_wallet_id: userWallet.id,
56	            p_amount: -amount
57	        });
58	
59	        if (balanceError) {
60	            // CHECK constraint violation means insufficient balance
61	            if (balanceError.code === '23514') {
62	                throw new Error('Insufficient balance');
63	            }
64	            throw new Error(balanceError.message);
65	        }
66	
67	        // 3. Log transaction with pending_transfer status BEFORE calling Asaas
68	        const { data: txRecord, error: txInsertError } = await supabaseAdmin
69	            .from('wallet_transactions')
70	            .insert({
71	                wallet_id: userWallet.id,
72	                amount: -amount,
73	                type: 'debit',
74	                description: `Saque via PIX (Worki 5%: R$${percentageFee.toFixed(2)} + operador financeiro: R$${WITHDRAW_FEE_FIXED.toFixed(2)} = R$${feeAmount.toFixed(2)} total, R$${netAmount.toFixed(2)} enviado)`,
75	                status: 'pending_transfer'
76	            })
77	            .select('id')
78	            .single();
79	
80	        if (txInsertError) {
81	            // Rollback balance since we couldn't create transaction record
82	            await supabaseAdmin.rpc('update_wallet_balance', {
83	                p_wallet_id: userWallet.id,
84	                p_amount: amount
85	            });
86	            throw new Error('Falha ao registrar transacao');
87	        }
88	
89	        // 4. Transfer from MASTER account to user's external PIX key
90	        const withdrawPayload = {
91	            value: netAmount,
92	            pixAddressKeyType: pixKeyType || 'CPF',
93	            pixAddressKey: pixKey,
94	            description: `Saque Worki - ${user.id.substring(0, 8)}`
95	        };
96	
97	        const withdrawRes = await fetch(`${ASAAS_API_URL}/transfers`, {
98	            method: 'POST',
99	            headers: getAsaasHeaders(),
100	            body: JSON.stringify(withdrawPayload)
101	        });
102	
103	        const withdrawData = await withdrawRes.json();
104	        if (!withdrawRes.ok) {
105	            // Mark transaction as failed
106	            await supabaseAdmin
107	                .from('wallet_transactions')
108	                .update({ status: 'failed', description: `Saque FALHOU: ${withdrawData.errors?.[0]?.description || 'Erro Asaas'}` })
109	                .eq('id', txRecord.id);
110	
111	            // Rollback: re-credit the balance since transfer failed
112	            const { error: rollbackError } = await supabaseAdmin.rpc('update_wallet_balance', {
113	                p_wallet_id: userWallet.id,
114	                p_amount: amount
115	            });
116	
117	            if (rollbackError) {
118	                console.error('CRITICAL: Rollback failed! User wallet deducted but transfer failed. Manual reconciliation needed.', {
119	                    userId: user.id,
120	                    walletId: userWallet.id,
121	                    transactionId: txRecord.id,
122	                    amount,
123	                    netAmount,
124	                    feeAmount,
125	                    asaasError: withdrawData,
126	                    rollbackError: rollbackError.message
127	                });
128	            }
129	
130	            console.error('Withdraw Transfer Error:', withdrawData);
131	            throw new Error(withdrawData.errors?.[0]?.description || 'Failed to transfer funds to external Pix');
132	        }
133	
134	        // 5. Transfer succeeded - update transaction to completed with reference
135	        await supabaseAdmin
136	            .from('wallet_transactions')
137	            .update({ status: 'completed', reference_id: withdrawData.id })
138	            .eq('id', txRecord.id);
139	
140	        return new Response(JSON.stringify({ success: true, transferId: withdrawData.id }), {
141	            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
142	            status: 200
143	        });
144	
145	    } catch (error: any) {
146	        console.error('Withdraw Error:', error);
147	        return new Response(JSON.stringify({ error: error.message }), {
148	            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
149	            status: 400,
150	        });
151	    }
