5	const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
6	
7	// Production IPs - log only in sandbox, enforce in production
8	const ASAAS_IPS = [
9	    '52.67.12.206',
10	    '18.230.8.159',
11	    '54.94.136.112',
12	    '54.94.183.101'
13	];
14	
15	serve(async (req) => {
16	    if (req.method === 'OPTIONS') {
17	        return new Response('ok', { headers: corsHeaders });
18	    }
19	
20	    try {
21	        const supabaseAdmin = createClient(
22	            Deno.env.get('SUPABASE_URL') ?? '',
23	            Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
24	        );
25	
26	        // --- 1. IP Check: log in sandbox, block in production ---
27	        const forwarded = req.headers.get('x-forwarded-for');
28	        const clientIp = forwarded ? forwarded.split(',')[0].trim() : 'unknown';
29	        const isProduction = Deno.env.get('ASAAS_ENVIRONMENT') === 'production';
30	
31	        if (!ASAAS_IPS.includes(clientIp)) {
32	            if (isProduction) {
33	                console.warn(`Blocked request from unauthorized IP: ${clientIp}`);
34	                return new Response('Unauthorized IP', { status: 403 });
35	            }
36	            console.log(`Sandbox: allowing request from IP ${clientIp}`);
37	        }
38	
39	        // --- 2. Security Check: Auth Token ---
40	        const asaasToken = req.headers.get('asaas-access-token');
41	        const expectedToken = Deno.env.get('ASAAS_WEBHOOK_TOKEN');
42	
43	        if (!expectedToken) {
44	            console.error('ASAAS_WEBHOOK_TOKEN not configured');
45	            return new Response('Server misconfigured', { status: 500 });
46	        }
47	
48	        if (asaasToken !== expectedToken) {
49	            console.warn('Blocked request: Invalid Webhook Token');
50	            return new Response('Unauthorized Token', { status: 401 });
51	        }
52	
53	        const bodyText = await req.text();
54	        if (!bodyText) {
55	            return new Response('Empty body', { status: 400 });
56	        }
57	
58	        let body;
59	        try {
60	            body = JSON.parse(bodyText);
61	        } catch (e) {
62	            return new Response('Invalid JSON', { status: 400 });
63	        }
64	
65	        const eventTarget = body.event;
66	
67	        // --- 3. Handle Transfer Events (withdrawal validation) ---
68	        if (eventTarget && eventTarget.startsWith('TRANSFER_')) {
69	            console.log('Received Transfer Webhook:', eventTarget, body.transfer?.id);
70	            return new Response(JSON.stringify({ status: "approved" }), {
71	                status: 200,
72	                headers: { 'Content-Type': 'application/json' }
73	            });
74	        }
75	
76	        if (!eventTarget && body.object === 'transfer') {
77	            console.log('Received Transfer Validation Payload:', body.id);
78	            return new Response(JSON.stringify({ status: "approved" }), {
79	                status: 200,
80	                headers: { 'Content-Type': 'application/json' }
81	            });
82	        }
83	
84	        // --- 4. Handle Payment Events (Deposits) - ATOMIC ---
85	        if (eventTarget === 'PAYMENT_RECEIVED' || eventTarget === 'PAYMENT_CONFIRMED') {
86	            const payment = body.payment;
87	
88	            if (!payment.externalReference) {
89	                return new Response('Ignored - No externalReference', { status: 200 });
90	            }
91	
92	            // Validate externalReference is a valid UUID
93	            if (!UUID_REGEX.test(payment.externalReference)) {
94	                console.warn('Invalid externalReference format:', payment.externalReference);
95	                return new Response('Bad Request - Invalid externalReference format', { status: 400 });
96	            }
97	
98	            // Validate payment.id and payment.value
99	            if (!payment.id || typeof payment.id !== 'string') {
100	                console.warn('Missing or invalid payment.id');
101	                return new Response('Bad Request - Missing payment.id', { status: 400 });
102	            }
103	
104	            if (!payment.value || typeof payment.value !== 'number' || payment.value <= 0) {
105	                console.warn('Missing or invalid payment.value:', payment.value);
106	                return new Response('Bad Request - Invalid payment.value', { status: 400 });
107	            }
108	
109	            const userId = payment.externalReference;
110	            const paymentId = payment.id;
111	            // Use netValue (what Asaas actually credited after gateway fees) if available, fallback to value
112	            const amount = (typeof payment.netValue === 'number' && payment.netValue > 0) ? payment.netValue : payment.value;
113	            if (payment.netValue !== undefined && payment.netValue !== payment.value) {
114	                console.log(`Deposit: gross=${payment.value}, net=${payment.netValue}, gateway_fee=${(payment.value - payment.netValue).toFixed(2)}`);
115	            }
116	
117	            // Use atomic RPC - handles dedup via unique constraint
118	            const { data: credited, error: rpcError } = await supabaseAdmin.rpc('credit_deposit', {
119	                p_user_id: userId,
120	                p_amount: amount,
121	                p_payment_id: paymentId,
122	                p_description: 'Deposito via Pix'
123	            });
124	
125	            if (rpcError) {
126	                console.error('credit_deposit RPC error:', rpcError);
127	                // If it's a unique constraint violation, it means already processed
128	                if (rpcError.code === '23505') {
129	                    return new Response('Already processed', { status: 200 });
130	                }
131	                throw new Error(rpcError.message);
132	            }
133	
134	            if (!credited) {
135	                return new Response('Already processed', { status: 200 });
136	            }
137	
138	            return new Response('Processed successfully', { status: 200 });
139	        }
140	
141	        return new Response('Event ignored', { status: 200 });
142	    } catch (error: any) {
143	        console.error('Webhook Error:', error);
144	        return new Response(JSON.stringify({ error: error.message }), {
145	            status: 400,
146	            headers: { 'Content-Type': 'application/json' }
147	        });
148	    }
149	});
