5	const MAX_PAGES = 10;
6	
7	serve(async (req) => {
8	    const corsHeaders = getCorsHeaders(req);
9	    if (req.method === 'OPTIONS') {
10	        return new Response('ok', { headers: corsHeaders });
11	    }
12	
