16	            throw new Error('ASAAS_API_KEY not configured');
17	        }
18	
19	        const supabaseAdmin = createClient(
20	            Deno.env.get('SUPABASE_URL') ?? '',
21	            Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
22	        );
23	
24	        const authHeader = req.headers.get('Authorization');
25	        if (!authHeader) throw new Error('Missing Authorization header');
26	        const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(authHeader.replace('Bearer ', ''));
27	        if (userError || !user) throw new Error('Invalid Token');
28	
29	        // Get user wallet
30	        const { data: wallet, error: walletError } = await supabaseAdmin
31	            .from('wallets')
32	            .select('id, balance')
33	            .eq('user_id', user.id)
34	            .single();
35	
36	        if (walletError || !wallet) {
37	            return new Response(JSON.stringify({
38	                success: true,
39	                hasUpdates: false,
40	                totalSynced: 0,
41	                message: 'Carteira nao encontrada.'
42	            }), {
43	                headers: { ...corsHeaders, 'Content-Type': 'application/json' },
44	                status: 200
45	            });
46	        }
47	
48	        let hasUpdates = false;
49	        let totalSynced = 0;
50	
51	        const statuses = ['RECEIVED', 'CONFIRMED'];
52	
53	        for (const status of statuses) {
54	            let offset = 0;
55	            const limit = 100;
56	            let hasMore = true;
57	            let pageCount = 0;
58	
59	            while (hasMore && pageCount < MAX_PAGES) {
60	                pageCount++;
61	                const asaasRes = await fetch(`${ASAAS_API_URL}/payments?externalReference=${user.id}&status=${status}&limit=${limit}&offset=${offset}`, {
62	                    headers: getAsaasHeaders()
63	                });
64	
65	                if (!asaasRes.ok) {
66	                    console.error('Error fetching Asaas payments:', await asaasRes.text());
67	                    break;
68	                }
69	
70	                const asaasData = await asaasRes.json();
71	                const payments = asaasData.data || [];
72	
73	                for (const payment of payments) {
74	                    const paymentId = payment.id;
75	                    const amount = payment.netValue ?? payment.value; // Use netValue (after Asaas fees)
76	
77	                    // Use atomic RPC - handles dedup via unique constraint
78	                    const { data: credited, error: rpcError } = await supabaseAdmin.rpc('credit_deposit', {
79	                        p_user_id: user.id,
80	                        p_amount: amount,
81	                        p_payment_id: paymentId,
82	                        p_description: 'Deposito sincronizado'
83	                    });
84	
85	                    if (rpcError) {
86	                        // Unique constraint = already processed, skip
87	                        if (rpcError.code === '23505') continue;
88	                        console.error('credit_deposit error:', rpcError);
89	                        continue;
90	                    }
91	
92	                    if (credited) {
93	                        totalSynced += amount;
94	                        hasUpdates = true;
95	                    }
96	                }
97	
98	                hasMore = payments.length === limit;
99	                offset += limit;
100	
101	                if (hasMore && pageCount >= MAX_PAGES) {
102	                    console.warn(`Max pages (${MAX_PAGES}) reached for status ${status}, user ${user.id}. Some payments may not be synced.`);
103	                }
104	            }
105	        }
106	
107	        return new Response(JSON.stringify({
108	            success: true,
109	            hasUpdates,
110	            totalSynced,
111	            message: hasUpdates ? `Sincronizados R$ ${totalSynced.toFixed(2)} de novos depositos.` : 'Tudo ja esta atualizado.'
112	        }), {
113	            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
114	            status: 200
115	        });
116	
117	    } catch (error: any) {
118	        console.error('Sync Error:', error);
119	        return new Response(JSON.stringify({ error: error.message }), {
120	            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
121	            status: 500,
122	        });
123	    }
124	});
